#include "window.h"
#include <QApplication>
#include <QTimer>
#include <QPixmap>
int main(int argc,char**argv){QApplication app(argc,argv);app.setApplicationName("Omadash");app.setOrganizationName("Omadash");bool capture=app.arguments().contains("--screenshot");OmadashWindow window(!capture);window.show();if(app.arguments().contains("--html")){auto thread=window.store.threads[0].toObject();auto messages=thread["messages"].toArray();auto message=messages.last().toObject();message["html"]="<div style='max-width:620px;margin:auto;background:#f0f3f6;padding:24px'><div style='background:#173d39;color:white;padding:32px'><p style='letter-spacing:3px;font-size:12px'>NORTHSTAR / WEEKLY</p><h1 style='font-family:Georgia;font-size:36px'>A little more room<br>for great work.</h1></div><div style='background:white;padding:28px'><h2>Your week, thoughtfully planned</h2><p>This sample checks designed HTML email inside the native thread reader.</p><table style='width:100%;border-collapse:collapse'><tr><td style='padding:16px;background:#e9f3eb'><b>Monday</b><br>Product review</td><td style='padding:16px;background:#f9ede3'><b>Thursday</b><br>Customer stories</td></tr></table><p><a href='https://example.com' style='display:inline-block;background:#173d39;color:white;padding:12px 20px;text-decoration:none'>Explore this week</a></p><p style='font-size:12px;color:#777'>Tables, colors, typography, spacing, and links.</p></div></div>";messages[messages.size()-1]=message;thread["messages"]=messages;window.store.threads[0]=thread;window.openThread(0);}if(app.arguments().contains("--thread")){window.openThread(0);window.selectMessage(0);window.compose("reply-all");window.toggleCalendar();}if(capture){int i=app.arguments().indexOf("--screenshot");QTimer::singleShot(2200,&window,[&,i]{window.grab().save(app.arguments().value(i+1));app.quit();});}return app.exec();}
